--[=[
    @class IServiceCollection

    服务描述集合
]=]

--[=[
    @type ImplementationType string | ModuleScript | IServiceFactory
    @within IServiceCollection
    实现类型，当解决服务时，会根据实现类型尝试不同的解决方案：
    * string: 将根据类型名称获取服务
    * ModuleScript: 将会 requier() 该脚本，并调用其构造函数以生成服务
    * IServiceFactory：将会执行该工厂函数以获得服务

]=]
export type ImplementationType = string | ModuleScript | IServiceFactory

export type IServiceCollection = {
    --- 添加服务描述
    Add: (self: IServiceCollection, descriptor: IServiceDescriptor) -> (),

    --- 获取服务描述数量
    Count: (self: IServiceCollection) -> number,

    --- 添加瞬时服务描述
    AddTransient: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> (),

    -- 添加后台服务
    -- @param alias string? -- 别名，可选项，之后可以使用 ServiceProvider:GetService(alias) 获取服务
    AddHostedService: (self: IServiceCollection, implementation: ImplementationType, alias: string?) -> (),

    --- 添加作用域服务描述
    AddScoped: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> (),

    --- 添加单例服务描述
    AddSingleton: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> (),

    --- 尝试添加瞬时服务描述，如果该 serviceType 已存在，则不添加
    TryAddTransient: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> (),

    --- 尝试添加后台服务描述，如果该 serviceType 已存在，则不添加
    TryAddHostedService: (self: IServiceCollection, implementation: ImplementationType) -> (),

    --- 尝试添加单例服务描述，如果该 serviceType 已存在，则不添加
    TryAddSingleton: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> (),

    --- 尝试添加作用域服务描述，如果该 serviceType 已存在，则不添加
    TryAddScoped: (self: IServiceCollection, serviceType: string, implementation: ImplementationType) -> ()
}&IServiceCollection_extensions -- 代码提示扩展

return {}
